def sheet(wb, title, headers, rows, widths):
    ws = wb.create_sheet(title)
    ws.append(headers)
    for c in ws[1]:
        c.font, c.fill, c.alignment, c.border = BOLD, HEAD, WRAP, BOX
    for r in rows:
        ws.append(list(r))
    for row in ws.iter_rows(min_row=2):
        for c in row:
            c.font, c.alignment, c.border = F, WRAP, BOX
    for i, w in enumerate(widths):
        ws.column_dimensions[chr(65 + i)].width = w
    ws.freeze_panes = "B2"
    return ws


def main():
    wb = Workbook()
    ov = wb.active; ov.title = "Overview"
    lines = [("Multimodal Hotel Intelligence Assistant: Testing and User Acceptance (document 08)", True), ("", False),
             ("What is tested: the prototype, against the business requirements (02) and the evaluation plan (07).", False),
             ("Business UAT: Tez, as the quality manager, runs each test in the app (http://localhost:8507) and fills in Actual result, Status and Date. Two tests ask for an answer, about 1 cent each.", False),
             ("System & AI tests: run by Claude (delivery) with evidence from the evaluation (evals/experiment-log.md, evals/results/); signed off by Tez.", False),
             ("Status values: Pass, Fail, Partly, Pending, Not run. Failures and partial passes are logged on the Defects sheet.", False),
             (f"Prepared {DATE}.", False)]
    for i, (t, b) in enumerate(lines, 1):
        ov.cell(row=i, column=1, value=t).font = Font(name="Arial", size=12 if b else 10, bold=b)
    ov.column_dimensions["A"].width = 140

    bu = sheet(wb, "Business UAT", ["ID", "Business question", "Tested by", "Scenario and data", "What the tester does", "Pass criteria",
                                    "Business outcome it proves", "Actual result", "Status", "Tester", "Date", "Notes"],
               [(i, q, "Tez (quality manager)", s, d, p, o, *(lambda r: (r[0], r[1], "Tez", r[2]))(BUSINESS_RESULTS.get(i, ("", "Pending", ""))), "")
                for i, q, s, d, p, o in BUSINESS],
               [7, 30, 14, 30, 30, 40, 28, 30, 10, 10, 10, 20])
    st = sheet(wb, "System & AI tests", ["ID", "Type", "Area", "Scenario", "Test data", "Steps", "Expected result", "Pass criteria",
                                         "Actual result", "Status", "Tester", "Date"],
               [(*r, ME, DATE) for r in SYSTEM], [7, 11, 26, 28, 22, 20, 26, 18, 40, 9, 15, 11])
    for ws, col, n in [(bu, "I", len(BUSINESS)), (st, "J", len(SYSTEM))]:
        dv = DataValidation(type="list", formula1='"' + ",".join(STATUSES) + '"', allow_blank=True)
        ws.add_data_validation(dv); dv.add(f"{col}2:{col}{n + 1}")

    sm = wb.create_sheet("Summary")
    sm.append(["Status", "Business UAT", "System & AI tests", "Total"])
    for i, s in enumerate(STATUSES, 2):
        sm.append([s, f"=COUNTIF('Business UAT'!I:I,A{i})", f"=COUNTIF('System & AI tests'!J:J,A{i})", f"=B{i}+C{i}"])
    sm.append(["Total", "=SUM(B2:B6)", "=SUM(C2:C6)", "=SUM(D2:D6)"])
    for row in sm.iter_rows():
        for c in row:
            c.font, c.border = (BOLD if c.row == 1 else Font(name="Arial", size=10, bold=c.row == 7)), BOX
            if c.row == 1:
                c.fill = HEAD
    for col in "ABCD":
        sm.column_dimensions[col].width = 20

    sheet(wb, "Defects", ["ID", "Found in", "Severity", "Description", "Suggested fix", "Status"], DEFECTS, [7, 14, 10, 60, 55, 11])
    wb.save(OUT)
    print(f"written {OUT.name}: {len(BUSINESS)} business tests, {len(SYSTEM)} system and AI tests, {len(DEFECTS)} defects")


if __name__ == "__main__":
    main()
